layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 2.841; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 2.841; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 6px; padding-bottom: 0px; padding-left: 6px; transition: all }
[data-ryt="nav"] a:hover { color: #FF4D4D }
[data-ryt="brand"]:hover { color: #FF4D4D }
